#!/usr/bin/env node
/**
 * Bundles Kira's model sources (kira/src/model) into one ES module the app can import:
 *   services/kira/kira-model.generated.js
 *
 * The order matches kira/tools/build.py. `--check` fails if the generated file is stale.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const modelDir = path.join(root, 'kira', 'src', 'model');
const out = path.join(root, 'services', 'kira', 'kira-model.generated.js');

const MODEL = [
  'canonical.js', 'unicode-data.js', 'unicode.js', 'artifact-data.js', 'artifact-checker.js',
  'query-types.js', 'query-checker.js', 'engine.js', 'parser.js', 'conversation.js',
  'dialogue-assets.js', 'dialogue.js',
];

// Session packing/validation lives in Kira's browser adapter but has no DOM dependency.
const source = [
  ...MODEL.map(name => path.join(modelDir, name)),
  path.join(root, 'kira', 'src', 'browser', 'persistence.js'),
].map(file => fs.readFileSync(file, 'utf8')).join('');
const generated = [
  '// GENERATED by scripts/build-kira-module.mjs from kira/src/model. Do not edit.',
  '// @ts-nocheck',
  source,
  'export default globalThis.Kira;',
  '',
].join('\n');

if (process.argv.includes('--check')) {
  const current = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
  if (current !== generated) {
    console.error('services/kira/kira-model.generated.js is stale. Run: npm run kira:build');
    process.exit(1);
  }
  console.log('Kira module is up to date.');
} else {
  fs.writeFileSync(out, generated);
  console.log(`Wrote ${path.relative(root, out)} (${generated.length.toLocaleString()} bytes)`);
}
